#!/usr/bin/env bash
# Creates the annotated release tag vX.Y.Z on HEAD. The message holds the release's notes,
# generated by git-cliff from the Conventional Commits since the last release tag.
# Never pushes: pushing the tag is what triggers .github/workflows/release.yml.
# Usage: release-tag.sh <git-cliff> <X.Y.Z>
set -euo pipefail
# shellcheck source=scripts/release-common.sh
source "$(dirname "${BASH_SOURCE[0]}")/release-common.sh"

cliff="${1:?usage: release-tag.sh <git-cliff> <X.Y.Z>}"
dirty="$(git status --porcelain)"
[[ -z "$dirty" ]] ||
  die "the work tree is not clean; the tag goes on the commit that passed the checks" "git status"
check_release_version release:tag "${2:-}"
grep -qF "## [$version] - " CHANGELOG.md ||
  die "CHANGELOG.md has no $version section" "task release:changelog -- $version, then commit and merge it"
notes="$(release_notes "$cliff")"

msg="$(mktemp)"
trap 'rm -f "$msg"' EXIT
printf 'kref v%s\n\n%s\n' "$version" "$notes" >"$msg"

git tag -a --cleanup=verbatim "v$version" -F "$msg"
head_sha="$(git rev-parse --short HEAD)"
echo "✓ tagged v$version on $head_sha"
echo "  review: git show v$version"
echo "  publish when ready (starts the release workflow): git push origin v$version"
